score alphabeta(depth, state,
    next_player, alpha, beta)
{
  if(final(state)||(depth==0))
    return score(state);
  else for all neighbour states
    if (next_player is
        minimising)
      score =
          min(alphabeta(depth-1,
          each_child,
              next_player,
              alpha, beta);
      if (score <= alpha) return
          alpha;
      if (score < beta) beta =
          score;
    else
      score =
          max(alphabeta(depth-1,
          each_child,
              next_player,
              alpha, beta);
      if (score >= beta) return
          beta;
      if (score > alpha) alpha =
          score;
  return score;
}
